for _kind, _en, _es, _extensions in [('Vídeo', 'Video', 'Video', ('MP4', 'MKV', 'WebM')), ('Áudio', 'Audio', 'Audio', ('MP3', 'M4A', 'OPUS', 'WAV', 'FLAC'))]:
    for _ext in _extensions:
        TRANSLATIONS[f'{_kind} · {_ext}'] = (f'{_en} · {_ext}', f'{_es} · {_ext}')


def translate(text, language):
    if language == 'Português':
        return text
    return TRANSLATIONS.get(text, (text, text))[0 if language == 'English' else 1]


def canonical(text):
    for source, alternatives in TRANSLATIONS.items():
        if text in (source, *alternatives):
            return source
    return text
